template <typename Traits>
inline void convert_node_vector3_global_to_local(flight::Ref<Vector3Like> out, Transform3DNode<Traits> source, flight::Ref<Vector3Like> point) {
  flight::Ref<Matrix4> inv = acquire_matrix4();
  inverse_matrix4(inv, get_node_world_matrix4<Traits>(source));
  matrix4_transform_point(out, inv, point);
  release_matrix4(inv);
}

template <typename Traits>
inline void convert_node_vector3_local_to_global(flight::Ref<Vector3Like> out, Transform3DNode<Traits> source, flight::Ref<Vector3Like> point) {
  matrix4_transform_point(out, get_node_world_matrix4<Traits>(source), point);
}

